func DecompressData(data []byte) ([]byte, error) {
	buf := bytes.NewBuffer(data)
	gz, err := gzip.NewReader(buf)
	if err != nil {
		return nil, fmt.Errorf("failed to create gzip reader: %v", err)
	}
	defer gz.Close()

	var decompressedData bytes.Buffer
	_, err = decompressedData.ReadFrom(gz)
	if err != nil {
		return nil, fmt.Errorf("failed to decompress data: %v", err)
	}

	return decompressedData.Bytes(), nil
}

func WriteByteStringToFile(filePath string, data []byte) error {
	err := os.WriteFile(filePath, data, 0644)
	if err != nil {
		return fmt.Errorf("failed to write file: %v", err)
	}
	return nil
}

func GenerateDefaultConfigFile(filePath string, serviceType string) error {
	var decompressedData []byte
	var err error

	if serviceType == "storaged" {
		decompressedData, err = DecompressData(Storaged_config_file)
	} else if serviceType == "graphd" {
		decompressedData, err = DecompressData(Graphd_config_file)
	} else if serviceType == "metad" {
		decompressedData, err = DecompressData(Metad_config_file)
	} else {
		return NgctlError("invalid service type", err.Error())
	}

	err = WriteByteStringToFile(filePath, decompressedData)
	if err != nil {
		return fmt.Errorf("failed to write file: %v", err)
	}
	return nil
}
